import React, { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, Alert, ActivityIndicator, ImageBackground, StatusBar, ScrollView } from 'react-native';
import api, { setAuthToken } from '../services/api';
import { useNavigation } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { LinearGradient } from 'expo-linear-gradient';
import { Ionicons } from '@expo/vector-icons';

const SignupScreen = ({ route }: any) => {
  const { setIsAuthenticated } = route.params || {};
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigation = useNavigation<any>();

  const handleSignup = async () => {
    if (!name || (!email && !phoneNumber) || !password) {
      Alert.alert('Error', 'Please fill in all required fields');
      return;
    }

    setLoading(true);
    try {
      const payload = {
        name,
        email,
        phoneNumber,
        password,
      };
      
      const response = await api.post('/auth/register', payload);
      const { token, user } = response.data;

      if (token) {
          setAuthToken(token);
          await AsyncStorage.setItem('auth_token', token);
          
          if (setIsAuthenticated) {
            setIsAuthenticated(true);
          }
          
          Alert.alert('Success', 'Account created successfully!', [
              { text: 'OK', onPress: () => navigation.navigate('MainTabs') }
          ]);
      } else {
           // Fallback if auto-login after register isn't supported, go to login
           Alert.alert('Success', 'Account created! Please login.', [
               { text: 'OK', onPress: () => navigation.navigate('Login') }
           ]);
      }

    } catch (error: any) {
      console.error(error);
      Alert.alert('Signup Failed', error.response?.data?.message || 'Could not create account');
    } finally {
      setLoading(false);
    }
  };

  return (
    <View style={styles.container}>
      <StatusBar barStyle="light-content" backgroundColor="#000" />
      <ImageBackground 
        source={{ uri: 'https://images.unsplash.com/photo-1541592106381-b31e9677c0e5?ixlib=rb-4.0.3&auto=format&fit=crop&w=1350&q=80' }} 
        style={styles.backgroundImage}
      >
        <LinearGradient
            colors={['rgba(0,0,0,0.3)', 'rgba(0,0,0,0.8)']}
            style={styles.overlay}
        >
            <ScrollView contentContainerStyle={styles.formContainer} showsVerticalScrollIndicator={false}>
                <Text style={styles.title}>Create Account</Text>
                <Text style={styles.subtitle}>Join Menha Boutique</Text>

                <View style={styles.inputWrapper}>
                    <Ionicons name="person-outline" size={20} color="#666" style={styles.inputIcon} />
                    <TextInput
                        style={styles.input}
                        placeholder="Full Name"
                        placeholderTextColor="#999"
                        value={name}
                        onChangeText={setName}
                    />
                </View>

                <View style={styles.inputWrapper}>
                    <Ionicons name="mail-outline" size={20} color="#666" style={styles.inputIcon} />
                    <TextInput
                        style={styles.input}
                        placeholder="Email Address"
                        placeholderTextColor="#999"
                        value={email}
                        onChangeText={setEmail}
                        keyboardType="email-address"
                        autoCapitalize="none"
                    />
                </View>

                <View style={styles.inputWrapper}>
                    <Ionicons name="call-outline" size={20} color="#666" style={styles.inputIcon} />
                    <TextInput
                        style={styles.input}
                        placeholder="Phone Number"
                        placeholderTextColor="#999"
                        value={phoneNumber}
                        onChangeText={setPhoneNumber}
                        keyboardType="phone-pad"
                    />
                </View>

                <View style={styles.inputWrapper}>
                    <Ionicons name="lock-closed-outline" size={20} color="#666" style={styles.inputIcon} />
                    <TextInput
                        style={styles.input}
                        placeholder="Password"
                        placeholderTextColor="#999"
                        value={password}
                        onChangeText={setPassword}
                        secureTextEntry
                    />
                </View>

                {/* Address Section */}
                <Text style={styles.sectionHeader}>Address Details</Text>
                
                <View style={styles.inputWrapper}>
                    <Ionicons name="location-outline" size={20} color="#666" style={styles.inputIcon} />
                    <TextInput
                        style={styles.input}
                        placeholder="Address Line"
                        placeholderTextColor="#999"
                        value={address}
                        onChangeText={setAddress}
                    />
                </View>

                <View style={styles.row}>
                    <View style={[styles.inputWrapper, { flex: 1, marginRight: 10 }]}>
                         <TextInput
                            style={styles.input}
                            placeholder="City"
                            placeholderTextColor="#999"
                            value={city}
                            onChangeText={setCity}
                        />
                    </View>
                    <View style={[styles.inputWrapper, { flex: 1 }]}>
                         <TextInput
                            style={styles.input}
                            placeholder="Pincode"
                            placeholderTextColor="#999"
                            value={postCode}
                            onChangeText={setPostCode}
                            keyboardType="number-pad"
                        />
                    </View>
                </View>

                <View style={styles.row}>
                    <View style={[styles.inputWrapper, { flex: 1, marginRight: 10 }]}>
                         <TextInput
                            style={styles.input}
                            placeholder="State"
                            placeholderTextColor="#999"
                            value={state}
                            onChangeText={setState}
                        />
                    </View>
                    <View style={[styles.inputWrapper, { flex: 1 }]}>
                         <TextInput
                            style={styles.input}
                            placeholder="Country"
                            placeholderTextColor="#999"
                            value={country}
                            onChangeText={setCountry}
                        />
                    </View>
                </View>

                <TouchableOpacity 
                    onPress={handleSignup} 
                    disabled={loading}
                    style={styles.signupBtnContainer}
                >
                    <LinearGradient
                        colors={['#f59e0b', '#f97316']}
                        start={{ x: 0, y: 0 }}
                        end={{ x: 1, y: 0 }}
                        style={styles.button}
                    >
                        {loading ? <ActivityIndicator color="#fff" /> : <Text style={styles.buttonText}>Sign Up</Text>}
                    </LinearGradient>
                </TouchableOpacity>

                <TouchableOpacity style={styles.linkButton} onPress={() => navigation.navigate('Login')}>
                    <Text style={styles.linkText}>Already have an account? <Text style={styles.linkHighlight}>Login</Text></Text>
                </TouchableOpacity>
            </ScrollView>
        </LinearGradient>
      </ImageBackground>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#000',
  },
  backgroundImage: {
    flex: 1,
    justifyContent: 'center',
  },
  overlay: {
    flex: 1,
    padding: 20,
  },
  formContainer: {
      flexGrow: 1,
      justifyContent: 'flex-end',
      paddingBottom: 20,
  },
  title: {
    fontSize: 32,
    fontWeight: 'bold',
    marginBottom: 5,
    color: '#fff',
    textAlign: 'center',
  },
  subtitle: {
    fontSize: 16,
    color: '#eee',
    marginBottom: 30,
    textAlign: 'center',
    opacity: 0.8,
  },
  inputWrapper: {
      flexDirection: 'row',
      alignItems: 'center',
      backgroundColor: '#fff',
      borderRadius: 12,
      marginBottom: 15,
      paddingHorizontal: 15,
      height: 55,
  },
  inputIcon: {
      marginRight: 10,
  },
  input: {
    flex: 1,
    height: '100%',
    color: '#333',
    fontSize: 16,
  },
  signupBtnContainer: {
      marginTop: 20,
      shadowColor: '#f97316',
      shadowOffset: { width: 0, height: 4 },
      shadowOpacity: 0.3,
      shadowRadius: 8,
      elevation: 5,
  },
  button: {
    height: 55,
    borderRadius: 30,
    justifyContent: 'center',
    alignItems: 'center',
  },
  buttonText: {
    color: '#fff',
    fontSize: 18,
    fontWeight: 'bold',
    letterSpacing: 0.5,
  },
  linkButton: {
    marginTop: 25,
    alignItems: 'center',
  },
  linkText: {
    color: '#fff',
    fontSize: 14,
  },
  linkHighlight: {
      fontWeight: 'bold',
      color: '#f59e0b',
  }
});

export default SignupScreen;
